"use client"

import * as React from "react"

// Theme configuration for light/dark mode
export const THEMES = { light: "", dark: ".dark" } as const

// Chart configuration type - matches shadcn/ui pattern
export type ChartConfig = {
  [key: string]: {
    label?: React.ReactNode
    icon?: React.ComponentType
  } & (
    | { color?: string; theme?: never }
    | { color?: never; theme: Record<keyof typeof THEMES, string> }
  )
}

// Default chart dimensions
export const DEFAULT_CHART_DIMENSIONS = {
  width: 600,
  height: 400,
  margin: { top: 20, right: 20, bottom: 40, left: 50 },
} as const

// Default chart colors (CSS variable references)
export const DEFAULT_CHART_COLORS = [
  "var(--chart-1)",
  "var(--chart-2)",
  "var(--chart-3)",
  "var(--chart-4)",
  "var(--chart-5)",
] as const

// Get color from config or fallback to default
export function getChartColor(
  config: ChartConfig | undefined,
  key: string,
  index: number
): string {
  if (config?.[key]?.color) {
    return config[key].color!
  }
  if (config?.[key]?.theme) {
    // Theme colors handled by CSS variables
    return `var(--color-${key})`
  }
  return DEFAULT_CHART_COLORS[index % DEFAULT_CHART_COLORS.length]
}

// Generate CSS variables from config
export function generateChartStyles(
  chartId: string,
  config: ChartConfig
): string {
  const colorConfig = Object.entries(config).filter(
    ([, cfg]) => cfg.theme || cfg.color
  )

  if (!colorConfig.length) return ""

  return Object.entries(THEMES)
    .map(
      ([theme, prefix]) => `
${prefix} [data-chart="${chartId}"] {
${colorConfig
  .map(([key, itemConfig]) => {
    const color =
      itemConfig.theme?.[theme as keyof typeof itemConfig.theme] ||
      itemConfig.color
    return color ? `  --color-${key}: ${color};` : null
  })
  .filter(Boolean)
  .join("\n")}
}`
    )
    .join("\n")
}

// Common data types
export interface ChartDataPoint {
  label: string
  value: number
  [key: string]: unknown
}

export interface ChartSeries {
  name: string
  data: ChartDataPoint[]
  color?: string
}

// Axis types
export type AxisOrientation = "top" | "right" | "bottom" | "left"
export type AxisScale = "linear" | "log" | "time" | "band" | "point"

// Common chart props
export interface BaseChartProps {
  className?: string
  config?: ChartConfig
  width?: number
  height?: number
  margin?: { top: number; right: number; bottom: number; left: number }
  showGrid?: boolean
  showTooltip?: boolean
  showLegend?: boolean
  /** Which side of the plot the persistent legend sits on. */
  legendPosition?: "top" | "bottom" | "left" | "right"
  animate?: boolean
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import {
  DEFAULT_CHART_DIMENSIONS,
  generateChartStyles,
  type ChartConfig,
} from "./chart-config"

// Chart context for sharing config across components
interface ChartContextValue {
  config: ChartConfig
  chartId: string
}

const ChartContext = React.createContext<ChartContextValue | null>(null)

export function useChart() {
  const context = React.useContext(ChartContext)
  if (!context) {
    throw new Error("useChart must be used within a ChartContainer")
  }
  return context
}

// Style injection component
function ChartStyle({ id, config }: { id: string; config: ChartConfig }) {
  const styles = generateChartStyles(id, config)
  if (!styles) return null

  return <style dangerouslySetInnerHTML={{ __html: styles }} />
}

// Main chart container
export interface ChartContainerProps extends React.HTMLAttributes<HTMLDivElement> {
  config?: ChartConfig
  children: React.ReactNode
}

export function ChartContainer({
  id,
  className,
  children,
  config = {},
  ...props
}: ChartContainerProps) {
  const uniqueId = React.useId()
  const chartId = `chart-${id || uniqueId.replace(/:/g, "")}`

  return (
    <ChartContext.Provider value={{ config, chartId }}>
      <div
        data-slot="chart"
        data-chart={chartId}
        className={cn(
          "flex aspect-video justify-center text-sm",
          "[&_.chart-grid-line]:stroke-border/40",
          "[&_.chart-axis-line]:stroke-border/60",
          "[&_.chart-axis-tick]:fill-muted-foreground",
          "[&_.chart-axis-label]:fill-muted-foreground",
          className
        )}
        {...props}
      >
        <ChartStyle id={chartId} config={config} />
        {children}
      </div>
    </ChartContext.Provider>
  )
}

// Responsive wrapper using ResizeObserver
export interface ResponsiveChartContainerProps extends ChartContainerProps {
  aspectRatio?: number
}

export function ResponsiveChartContainer({
  aspectRatio = 16 / 9,
  children,
  ...props
}: ResponsiveChartContainerProps) {
  const containerRef = React.useRef<HTMLDivElement>(null)
  const [dimensions, setDimensions] = React.useState<{
    width: number
    height: number
  }>({
    width: DEFAULT_CHART_DIMENSIONS.width,
    height: DEFAULT_CHART_DIMENSIONS.height,
  })

  React.useEffect(() => {
    if (!containerRef.current) return

    const resizeObserver = new ResizeObserver((entries) => {
      for (const entry of entries) {
        const { width } = entry.contentRect
        setDimensions({
          width: Math.round(width),
          height: Math.round(width / aspectRatio),
        })
      }
    })

    resizeObserver.observe(containerRef.current)
    return () => resizeObserver.disconnect()
  }, [aspectRatio])

  return (
    <div ref={containerRef} className="w-full">
      <ChartContainer {...props}>
        {React.Children.map(children, (child) => {
          if (
            React.isValidElement<{ width?: number; height?: number }>(child)
          ) {
            return React.cloneElement(child, {
              width: dimensions.width,
              height: dimensions.height,
            })
          }
          return child
        })}
      </ChartContainer>
    </div>
  )
}

export { ChartContext }

"use client"

import * as React from "react"
import type { ScaleBand, ScaleLinear, ScaleTime } from "d3-scale"

import { cn } from "@/lib/utils"

type AnyScale =
  | ScaleLinear<number, number>
  | ScaleBand<string>
  | ScaleTime<number, number>

export interface ChartAxisProps {
  scale: AnyScale
  orientation: "top" | "right" | "bottom" | "left"
  transform?: string
  tickCount?: number
  tickFormat?: (value: unknown) => string
  tickSize?: number
  label?: string
  className?: string
  hideAxisLine?: boolean
  hideTickMarks?: boolean
}

export function ChartAxis({
  scale,
  orientation,
  transform,
  tickCount = 5,
  tickFormat,
  tickSize = 6,
  label,
  className,
  hideAxisLine = false,
  hideTickMarks = false,
}: ChartAxisProps) {
  const isHorizontal = orientation === "top" || orientation === "bottom"
  const isLeft = orientation === "left"
  const isTop = orientation === "top"

  // Get ticks based on scale type
  const ticks = React.useMemo(() => {
    if ("ticks" in scale && typeof scale.ticks === "function") {
      return scale.ticks(tickCount)
    }
    if ("domain" in scale && typeof scale.domain === "function") {
      const domain = scale.domain()
      if (domain.length <= tickCount) return domain
      // Band scales used to return the full domain unconditionally —
      // a 120-day price series rendered 120 X labels into an
      // unreadable overlapping mass while `tickCount` was silently
      // ignored. Evenly sample the categorical domain to `tickCount`
      // labels so band-scale charts behave like linear/time-scale
      // charts at high density (those already auto-thin via d3's
      // `.ticks(tickCount)`).
      const step = (domain.length - 1) / (tickCount - 1)
      const selected = new Set<number>()
      for (let i = 0; i < tickCount; i++) {
        selected.add(Math.round(i * step))
      }
      // `filter` preserves the original element type union (no narrowing
      // gymnastics with `as`), and the index-based selection guarantees
      // first + last + evenly spaced middle.
      return domain.filter((_, idx) => selected.has(idx))
    }
    return []
  }, [scale, tickCount])

  // Get tick position
  const getTickPosition = (tick: unknown): number => {
    if ("bandwidth" in scale && typeof scale.bandwidth === "function") {
      const bandScale = scale as ScaleBand<string>
      return (bandScale(tick as string) ?? 0) + bandScale.bandwidth() / 2
    }
    return (scale as ScaleLinear<number, number>)(tick as number)
  }

  // Format tick value
  const formatTick = (tick: unknown): string => {
    if (tickFormat) return tickFormat(tick)
    if (tick instanceof Date) return tick.toLocaleDateString()
    if (typeof tick === "number") {
      if (Math.abs(tick) >= 1000000) return `${(tick / 1000000).toFixed(1)}M`
      if (Math.abs(tick) >= 1000) return `${(tick / 1000).toFixed(1)}K`
      return tick.toLocaleString()
    }
    return String(tick)
  }

  const range = scale.range()
  const rangeStart = Math.min(...range)
  const rangeEnd = Math.max(...range)

  return (
    <g className={cn("chart-axis", className)} transform={transform}>
      {/* Axis line */}
      {!hideAxisLine && (
        <line
          className="chart-axis-line"
          x1={isHorizontal ? rangeStart : 0}
          x2={isHorizontal ? rangeEnd : 0}
          y1={isHorizontal ? 0 : rangeStart}
          y2={isHorizontal ? 0 : rangeEnd}
          stroke="currentColor"
          strokeWidth={1}
          strokeOpacity={0.2}
        />
      )}

      {/* Ticks */}
      {ticks.map((tick, i) => {
        const position = getTickPosition(tick)
        const tickX = isHorizontal ? position : 0
        const tickY = isHorizontal ? 0 : position

        return (
          <g key={i} transform={`translate(${tickX}, ${tickY})`}>
            {/* Tick mark */}
            {!hideTickMarks && (
              <line
                className="chart-axis-tick"
                x2={isHorizontal ? 0 : isLeft ? -tickSize : tickSize}
                y2={isHorizontal ? (isTop ? -tickSize : tickSize) : 0}
                stroke="currentColor"
                strokeWidth={1}
                strokeOpacity={0.2}
              />
            )}

            {/* Tick label - LARGER TEXT */}
            <text
              className="chart-axis-label"
              style={{ fontSize: "12px" }}
              x={isHorizontal ? 0 : isLeft ? -tickSize - 8 : tickSize + 8}
              y={isHorizontal ? (isTop ? -tickSize - 8 : tickSize + 16) : 0}
              textAnchor={isHorizontal ? "middle" : isLeft ? "end" : "start"}
              dominantBaseline={isHorizontal ? "auto" : "middle"}
              fill="currentColor"
            >
              {formatTick(tick)}
            </text>
          </g>
        )
      })}

      {/* Axis label - LARGER TEXT */}
      {label && (
        <text
          className="chart-axis-label"
          style={{ fontSize: "13px", fontWeight: 500 }}
          x={isHorizontal ? (rangeStart + rangeEnd) / 2 : 0}
          y={isHorizontal ? (isTop ? -36 : 44) : (rangeStart + rangeEnd) / 2}
          textAnchor="middle"
          dominantBaseline={isHorizontal ? "auto" : "middle"}
          transform={
            !isHorizontal
              ? `rotate(-90, ${isLeft ? -48 : 48}, ${(rangeStart + rangeEnd) / 2})`
              : undefined
          }
          fill="currentColor"
        >
          {label}
        </text>
      )}
    </g>
  )
}

"use client"

import * as React from "react"
import type { ScaleLinear } from "d3-scale"

import { cn } from "@/lib/utils"

export interface ChartGridProps {
  xScale?: ScaleLinear<number, number>
  yScale?: ScaleLinear<number, number>
  width: number
  height: number
  xTickCount?: number
  yTickCount?: number
  strokeDasharray?: string
  className?: string
}

export function ChartGrid({
  xScale,
  yScale,
  width,
  height,
  xTickCount = 5,
  yTickCount = 5,
  strokeDasharray = "3,3",
  className,
}: ChartGridProps) {
  const xTicks = xScale?.ticks(xTickCount) ?? []
  const yTicks = yScale?.ticks(yTickCount) ?? []

  return (
    <g className={cn("chart-grid", className)}>
      {/* Horizontal grid lines */}
      {yTicks.map((tick, i) => (
        <line
          key={`h-${i}`}
          className="chart-grid-line"
          x1={0}
          x2={width}
          y1={yScale!(tick)}
          y2={yScale!(tick)}
          stroke="currentColor"
          strokeDasharray={strokeDasharray}
          strokeOpacity={0.3}
        />
      ))}

      {/* Vertical grid lines */}
      {xTicks.map((tick, i) => (
        <line
          key={`v-${i}`}
          className="chart-grid-line"
          x1={xScale!(tick)}
          x2={xScale!(tick)}
          y1={0}
          y2={height}
          stroke="currentColor"
          strokeDasharray={strokeDasharray}
          strokeOpacity={0.3}
        />
      ))}
    </g>
  )
}

// Simple horizontal-only grid
export interface ChartHorizontalGridProps {
  scale: ScaleLinear<number, number>
  width: number
  tickCount?: number
  strokeDasharray?: string
  className?: string
}

export function ChartHorizontalGrid({
  scale,
  width,
  tickCount = 5,
  strokeDasharray = "",
  className,
}: ChartHorizontalGridProps) {
  const ticks = scale.ticks(tickCount)

  return (
    <g className={cn("chart-grid", className)}>
      {ticks.map((tick, i) => (
        <line
          key={i}
          className="chart-grid-line"
          x1={0}
          x2={width}
          y1={scale(tick)}
          y2={scale(tick)}
          stroke="currentColor"
          strokeDasharray={strokeDasharray}
          strokeOpacity={0.15}
        />
      ))}
    </g>
  )
}

// Simple vertical-only grid
export interface ChartVerticalGridProps {
  scale: { ticks: (count?: number) => unknown[]; (value: unknown): number }
  height: number
  tickCount?: number
  strokeDasharray?: string
  className?: string
}

export function ChartVerticalGrid({
  scale,
  height,
  tickCount = 5,
  strokeDasharray = "3,3",
  className,
}: ChartVerticalGridProps) {
  const ticks = scale.ticks(tickCount)

  return (
    <g className={cn("chart-grid", className)}>
      {ticks.map((tick, i) => (
        <line
          key={i}
          className="chart-grid-line"
          x1={scale(tick)}
          x2={scale(tick)}
          y1={0}
          y2={height}
          stroke="currentColor"
          strokeDasharray={strokeDasharray}
          strokeOpacity={0.3}
        />
      ))}
    </g>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import type { ChartConfig } from "./chart-config"
import { useChart } from "./chart-container"

export interface TooltipData {
  label: string
  value: number | string
  color?: string
  category?: string
  [key: string]: unknown
}

export interface ChartTooltipProps {
  active?: boolean
  payload?: TooltipData | TooltipData[]
  position?: { x: number; y: number }
  className?: string
  formatter?: (value: number | string, name: string) => React.ReactNode
  labelFormatter?: (label: string) => React.ReactNode
  hideLabel?: boolean
  hideIndicator?: boolean
  indicator?: "dot" | "line" | "dashed"
}

export function ChartTooltip({
  active = true,
  payload,
  position,
  className,
  formatter,
  labelFormatter,
  hideLabel = false,
  hideIndicator = false,
  indicator = "dot",
}: ChartTooltipProps) {
  const { config } = useChart()

  if (!active || !payload) return null

  const items = Array.isArray(payload) ? payload : [payload]

  return (
    <div
      className={cn(
        "pointer-events-none absolute z-50",
        "border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl",
        "min-w-[8rem]",
        className
      )}
      style={position ? { left: position.x, top: position.y } : undefined}
    >
      {/* Label */}
      {!hideLabel && items[0]?.label && (
        <div className="mb-1 font-medium">
          {labelFormatter ? labelFormatter(items[0].label) : items[0].label}
        </div>
      )}

      {/* Items */}
      <div className="flex flex-col gap-1">
        {items.map((item, index) => {
          const itemConfig = config[item.category ?? item.label] ?? {}
          const color =
            item.color ?? itemConfig.color ?? `var(--chart-${index + 1})`

          return (
            <div
              key={index}
              className="flex items-center justify-between gap-4"
            >
              <div className="flex items-center gap-1.5">
                {/* Indicator */}
                {!hideIndicator && (
                  <div
                    className={cn(
                      "shrink-0 rounded-[2px]",
                      indicator === "dot" && "h-2.5 w-2.5",
                      indicator === "line" && "h-2.5 w-1",
                      indicator === "dashed" &&
                        "h-2.5 w-0 border-l-[1.5px] border-dashed"
                    )}
                    style={{
                      backgroundColor:
                        indicator !== "dashed" ? color : undefined,
                      borderColor: color,
                    }}
                  />
                )}

                {/* Name */}
                <span className="text-muted-foreground">
                  {itemConfig.label ?? item.category ?? item.label}
                </span>
              </div>

              {/* Value */}
              <span className="text-foreground font-mono font-medium tabular-nums">
                {formatter
                  ? formatter(item.value, item.label)
                  : typeof item.value === "number"
                    ? item.value.toLocaleString()
                    : item.value}
              </span>
            </div>
          )
        })}
      </div>
    </div>
  )
}

// Tooltip wrapper that tracks mouse position
export interface ChartTooltipWrapperProps {
  children: React.ReactNode
  content: React.ReactNode
  className?: string
}

export function ChartTooltipWrapper({
  children,
  content,
  className,
}: ChartTooltipWrapperProps) {
  const [position, setPosition] = React.useState<{
    x: number
    y: number
  } | null>(null)
  const containerRef = React.useRef<HTMLDivElement>(null)

  const handleMouseMove = (e: React.MouseEvent) => {
    if (!containerRef.current) return
    const rect = containerRef.current.getBoundingClientRect()
    setPosition({
      x: e.clientX - rect.left + 10,
      y: e.clientY - rect.top - 10,
    })
  }

  const handleMouseLeave = () => {
    setPosition(null)
  }

  return (
    <div
      ref={containerRef}
      className={cn("relative", className)}
      onMouseMove={handleMouseMove}
      onMouseLeave={handleMouseLeave}
    >
      {children}
      {position && (
        <div
          className="pointer-events-none absolute z-50"
          style={{ left: position.x, top: position.y }}
        >
          {content}
        </div>
      )}
    </div>
  )
}

// Simple tooltip content component
export interface ChartTooltipContentProps {
  label?: string
  value?: number | string
  color?: string
  className?: string
}

export function ChartTooltipContent({
  label,
  value,
  color,
  className,
}: ChartTooltipContentProps) {
  return (
    <div
      className={cn(
        "border-border/50 bg-background rounded-lg border px-2.5 py-1.5 text-xs shadow-xl",
        className
      )}
    >
      <div className="flex items-center gap-2">
        {color && (
          <div
            className="h-2.5 w-2.5 shrink-0 rounded-[2px]"
            style={{ backgroundColor: color }}
          />
        )}
        <span className="text-muted-foreground">{label}</span>
        {value !== undefined && (
          <span className="text-foreground font-mono font-medium tabular-nums">
            {typeof value === "number" ? value.toLocaleString() : value}
          </span>
        )}
      </div>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

import type { ChartConfig } from "./chart-config"
import { useChart } from "./chart-container"

export type LegendPosition = "top" | "bottom" | "left" | "right"

export interface LegendItem {
  name: string
  color: string
  value?: number | string
}

export interface ChartLegendProps {
  items?: LegendItem[]
  className?: string
  position?: LegendPosition
  hideIcon?: boolean
  onItemClick?: (name: string) => void
  onItemHover?: (name: string | null) => void
  /** When provided, items for which this returns `false` render dimmed —
   * used to show which series is highlighted after a legend click/hover. */
  isItemActive?: (name: string) => boolean
}

export function ChartLegend({
  items,
  className,
  position = "bottom",
  hideIcon = false,
  onItemClick,
  onItemHover,
  isItemActive,
}: ChartLegendProps) {
  const { config } = useChart()

  // Generate items from config if not provided
  const legendItems: LegendItem[] = React.useMemo(() => {
    if (items) return items

    return Object.entries(config).map(([key, value], index) => ({
      name: (value.label as string) ?? key,
      color: value.color ?? `var(--chart-${index + 1})`,
    }))
  }, [items, config])

  if (!legendItems.length) return null

  const isVertical = position === "left" || position === "right"

  return (
    <div
      className={cn(
        "flex items-center justify-center gap-6",
        isVertical && "max-h-full flex-col items-start gap-3 overflow-y-auto",
        position === "top" && "pb-4",
        position === "bottom" && "pt-4",
        position === "left" && "pr-4",
        position === "right" && "pl-4",
        className
      )}
    >
      {legendItems.map((item, index) => (
        <button
          key={index}
          type="button"
          aria-pressed={isItemActive ? !isItemActive(item.name) : undefined}
          className={cn(
            "flex items-center gap-2 text-sm",
            "transition-opacity hover:opacity-80",
            onItemClick && "cursor-pointer",
            isItemActive && !isItemActive(item.name) && "opacity-40"
          )}
          onClick={() => onItemClick?.(item.name)}
          onMouseEnter={() => onItemHover?.(item.name)}
          onMouseLeave={() => onItemHover?.(null)}
        >
          {!hideIcon && (
            <div
              className="size-3 shrink-0 rounded-sm"
              style={{ backgroundColor: item.color }}
            />
          )}
          <span className="text-foreground font-medium">{item.name}</span>
          {item.value !== undefined && (
            <span className="text-muted-foreground font-mono tabular-nums">
              {typeof item.value === "number"
                ? item.value.toLocaleString()
                : item.value}
            </span>
          )}
        </button>
      ))}
    </div>
  )
}

// Inline legend for embedding inside chart SVG
export interface ChartLegendInlineProps {
  items: LegendItem[]
  x?: number
  y?: number
  direction?: "horizontal" | "vertical"
  className?: string
}

export function ChartLegendInline({
  items,
  x = 0,
  y = 0,
  direction = "horizontal",
  className,
}: ChartLegendInlineProps) {
  const spacing = direction === "horizontal" ? 100 : 24

  return (
    <g
      className={cn("chart-legend", className)}
      transform={`translate(${x}, ${y})`}
    >
      {items.map((item, index) => (
        <g
          key={index}
          transform={
            direction === "horizontal"
              ? `translate(${index * spacing}, 0)`
              : `translate(0, ${index * spacing})`
          }
        >
          <rect width={12} height={12} rx={2} fill={item.color} />
          <text
            x={18}
            y={10}
            className="fill-foreground"
            style={{ fontSize: "13px", fontWeight: 500 }}
          >
            {item.name}
          </text>
        </g>
      ))}
    </g>
  )
}

// ============================================================================
// Series highlight — Plotly-style legend emphasis
// ============================================================================

/**
 * Shared selection/hover state for multi-series charts. Clicking a legend
 * item "selects" a series (persists until clicked again); hovering a legend
 * item previews it. The focused series (hover takes precedence over the
 * click selection) is emphasized while every other series renders dimmed —
 * faded, never removed — mirroring Plotly's legend highlight behavior.
 *
 *   const hl = useSeriesHighlight()
 *   <path className={cn(hl.isDimmed(name) && "opacity-30")} />
 *   <ChartLegend onItemClick={hl.toggle} onItemHover={hl.setHovered}
 *     isItemActive={hl.isActive} />
 */
export function useSeriesHighlight() {
  const [selected, setSelected] = React.useState<string | null>(null)
  const [hovered, setHovered] = React.useState<string | null>(null)
  const focused = hovered ?? selected

  const isDimmed = React.useCallback(
    (name: string) => focused !== null && focused !== name,
    [focused]
  )
  const isActive = React.useCallback(
    (name: string) => focused === null || focused === name,
    [focused]
  )
  const toggle = React.useCallback(
    (name: string) => setSelected((prev) => (prev === name ? null : name)),
    []
  )

  return {
    /** Series pinned by a legend click (null when none). */
    selected,
    /** Series currently hovered in the legend (null when none). */
    hovered,
    /** Effective emphasized series: hover wins over the click selection. */
    focused,
    setSelected,
    setHovered,
    /** Click handler for a legend item — pin/unpin the series. */
    toggle,
    /** True when a different series is focused (this one should fade). */
    isDimmed,
    /** True when this series is focused or nothing is focused. */
    isActive,
  }
}

// ============================================================================
// Legend layout — arranges the plot and a persistent legend on any side
// ============================================================================

/**
 * Positions a persistent `ChartLegend` on any side of the plot without
 * disturbing the plot's own coordinate system. The plot (svg + any
 * absolutely-positioned tooltips/overlays) is wrapped in a `relative`
 * flex-1 box so its overlays stay anchored to the plot area regardless of
 * which side the legend occupies. Render this as the sole flex child of a
 * `ChartContainer`.
 */
export function ChartLegendLayout({
  position = "right",
  show = true,
  legend,
  children,
  className,
}: {
  position?: LegendPosition
  show?: boolean
  legend: React.ReactNode
  children: React.ReactNode
  className?: string
}) {
  const isRow = position === "left" || position === "right"
  const legendFirst = position === "top" || position === "left"

  return (
    <div
      className={cn(
        "flex min-h-0 min-w-0 flex-1",
        isRow ? "flex-row" : "flex-col",
        className
      )}
    >
      {show && legendFirst && legend}
      <div className="relative flex min-h-0 min-w-0 flex-1">{children}</div>
      {show && !legendFirst && legend}
    </div>
  )
}

// Legend content for use with shadcn patterns
export interface ChartLegendContentProps {
  payload?: Array<{
    value: string
    color: string
    dataKey?: string
    type?: string
  }>
  verticalAlign?: "top" | "bottom"
  hideIcon?: boolean
  nameKey?: string
  className?: string
}

export function ChartLegendContent({
  payload,
  verticalAlign = "bottom",
  hideIcon = false,
  nameKey,
  className,
}: ChartLegendContentProps) {
  const { config } = useChart()

  if (!payload?.length) return null

  return (
    <div
      className={cn(
        "flex items-center justify-center gap-6",
        verticalAlign === "top" ? "pb-4" : "pt-4",
        className
      )}
    >
      {payload
        .filter((item) => item.type !== "none")
        .map((item, index) => {
          const key = nameKey ?? item.dataKey ?? "value"
          const itemConfig = config[key] ?? {}

          return (
            <div key={index} className="flex items-center gap-2 text-sm">
              {!hideIcon && (
                <div
                  className="size-3 shrink-0 rounded-sm"
                  style={{ backgroundColor: item.color }}
                />
              )}
              <span className="text-foreground font-medium">
                {(itemConfig.label as string) ?? item.value}
              </span>
            </div>
          )
        })}
    </div>
  )
}

"use client"

import * as React from "react"
import type { ScaleBand } from "d3-scale"

import { cn } from "@/lib/utils"

export interface ChartDragRange {
  x0: number
  x1: number
}

export interface UseChartZoomOptions {
  /** Ref to the chart's root <svg> — needed to convert client coords to
   * local plot-area coords via getScreenCTM, since the SVG may be scaled
   * by CSS relative to its viewBox. */
  svgRef: React.RefObject<SVGSVGElement | null>
  /** Left margin of the plot area (chart's `margin.left`). */
  marginLeft: number
  /** Width of the plot area (chart's `innerWidth`). */
  innerWidth: number
  disabled?: boolean
  /** Minimum drag distance (px) before a drag counts as a zoom selection
   * instead of a click. */
  minDragPx?: number
  onZoom: (range: ChartDragRange) => void
  onReset: () => void
}

export interface UseChartZoomResult {
  /** Current in-progress drag selection, in plot-area-local pixels. */
  dragRange: ChartDragRange | null
  isDragging: boolean
  handlers: {
    onMouseDown: (e: React.MouseEvent) => void
    onMouseMove: (e: React.MouseEvent) => void
    onMouseUp: (e: React.MouseEvent) => void
    onMouseLeave: (e: React.MouseEvent) => void
    onDoubleClick: (e: React.MouseEvent) => void
  }
}

function getLocalX(
  svg: SVGSVGElement | null,
  clientX: number,
  clientY: number,
  marginLeft: number
): number | null {
  if (!svg) return null
  const pt = svg.createSVGPoint()
  pt.x = clientX
  pt.y = clientY
  const ctm = svg.getScreenCTM()
  if (!ctm) return null
  const local = pt.matrixTransform(ctm.inverse())
  return local.x - marginLeft
}

/**
 * Drag-to-zoom for D3/SVG charts — mirrors Plotly.js's click-drag box
 * zoom: drag horizontally across the plot area to zoom the x-domain into
 * the selected range, double-click to reset. Consumers are responsible
 * for turning the emitted pixel range into a data-domain range (via
 * `scale.invert()` for continuous scales, or `getBandScaleIndexRange`
 * below for band scales) and re-filtering their data.
 */
export function useChartZoom({
  svgRef,
  marginLeft,
  innerWidth,
  disabled = false,
  minDragPx = 6,
  onZoom,
  onReset,
}: UseChartZoomOptions): UseChartZoomResult {
  const [dragStart, setDragStart] = React.useState<number | null>(null)
  const [dragRange, setDragRange] = React.useState<ChartDragRange | null>(null)

  const clamp = React.useCallback(
    (x: number) => Math.min(Math.max(x, 0), innerWidth),
    [innerWidth]
  )

  const onMouseDown = React.useCallback(
    (e: React.MouseEvent) => {
      if (disabled || e.button !== 0) return
      const x = getLocalX(svgRef.current, e.clientX, e.clientY, marginLeft)
      if (x === null) return
      const clamped = clamp(x)
      setDragStart(clamped)
      setDragRange({ x0: clamped, x1: clamped })
    },
    [disabled, svgRef, marginLeft, clamp]
  )

  const onMouseMove = React.useCallback(
    (e: React.MouseEvent) => {
      if (dragStart === null) return
      const x = getLocalX(svgRef.current, e.clientX, e.clientY, marginLeft)
      if (x === null) return
      setDragRange({ x0: dragStart, x1: clamp(x) })
    },
    [dragStart, svgRef, marginLeft, clamp]
  )

  const endDrag = React.useCallback(() => {
    setDragStart((start) => {
      if (start !== null) {
        setDragRange((range) => {
          if (range) {
            const width = Math.abs(range.x1 - range.x0)
            if (width >= minDragPx) {
              onZoom({
                x0: Math.min(range.x0, range.x1),
                x1: Math.max(range.x0, range.x1),
              })
            }
          }
          return null
        })
      }
      return null
    })
  }, [minDragPx, onZoom])

  const onMouseUp = React.useCallback(() => endDrag(), [endDrag])
  const onMouseLeave = React.useCallback(() => endDrag(), [endDrag])

  const onDoubleClick = React.useCallback(
    (e: React.MouseEvent) => {
      if (disabled) return
      e.preventDefault()
      onReset()
    },
    [disabled, onReset]
  )

  return {
    dragRange: dragStart !== null ? dragRange : null,
    isDragging: dragStart !== null,
    handlers: {
      onMouseDown,
      onMouseMove,
      onMouseUp,
      onMouseLeave,
      onDoubleClick,
    },
  }
}

/**
 * Translates a pixel drag range into a [startIndex, endIndex] window over
 * a band scale's domain — used to zoom categorical/band-scale x-axes
 * (e.g. candlestick dates, bar categories) by index rather than value.
 */
export function getBandScaleIndexRange(
  scale: ScaleBand<string>,
  x0: number,
  x1: number
): [number, number] {
  const domain = scale.domain()
  const step = scale.step() || 1
  let start = Math.floor(x0 / step)
  let end = Math.ceil(x1 / step) - 1
  start = Math.max(0, Math.min(start, domain.length - 1))
  end = Math.max(0, Math.min(end, domain.length - 1))
  if (end < start) end = start
  return [start, end]
}

/** The translucent selection rectangle drawn while dragging. Render as a
 * direct child of the chart's inner `<g transform="translate(margin...)">`. */
export function ChartZoomSelectionRect({
  range,
  height,
  className,
}: {
  range: ChartDragRange | null
  height: number
  className?: string
}) {
  if (!range) return null
  const x = Math.min(range.x0, range.x1)
  const width = Math.abs(range.x1 - range.x0)
  return (
    <rect
      x={x}
      y={0}
      width={width}
      height={height}
      className={cn("fill-primary/10 stroke-primary/50", className)}
      strokeWidth={1}
      style={{ pointerEvents: "none" }}
    />
  )
}

/** Small floating "Reset zoom" pill — only render when the chart is
 * currently zoomed. Position the containing element `relative`. */
export function ChartZoomResetButton({
  visible,
  onReset,
  className,
}: {
  visible: boolean
  onReset: () => void
  className?: string
}) {
  if (!visible) return null
  return (
    <button
      type="button"
      onClick={onReset}
      className={cn(
        "border-border/50 bg-background/95 text-muted-foreground hover:text-foreground absolute top-2 right-2 z-20 rounded-md border px-2 py-1 text-xs font-medium shadow-sm transition-colors",
        className
      )}
    >
      Reset zoom
    </button>
  )
}

// ============================================
// Category window — pointer, wheel and pinch
// ============================================

export interface UseChartWindowOptions {
  /** Categories in the full dataset. */
  length: number
  /** Fewest categories a zoom may leave visible. */
  minSpan?: number
  disabled?: boolean
  /** Screen axis the categories run along. */
  orientation?: "x" | "y"
  /**
   * Plot-area insets inside the bound element, px. Without them a pointer
   * over the third bar maps to the second, because the axis gutter and
   * margins are part of the element but not part of the plot.
   */
  insetStart?: number
  insetEnd?: number
  /**
   * Let a bare wheel zoom. Off by default: a chart that swallows scroll is
   * a trap halfway down a page, so ⌘/ctrl+wheel is the opt-in.
   */
  wheelZoom?: boolean
}

export interface ChartWindowSelection {
  /** Fractions of the plot area, 0–1, in gesture order. */
  from: number
  to: number
}

export interface UseChartWindowResult {
  start: number
  end: number
  span: number
  isZoomed: boolean
  /** The visible slice of the caller's data. */
  slice: <T>(data: T[]) => T[]
  /** In-progress drag selection, for the overlay. */
  selection: ChartWindowSelection | null
  zoomIn: () => void
  zoomOut: () => void
  reset: () => void
  setWindow: (start: number, end: number) => void
  /** Spread onto the element wrapping the plot. */
  bind: {
    ref: React.RefObject<HTMLDivElement | null>
    style: React.CSSProperties
  }
}

const clamp = (v: number, lo: number, hi: number) =>
  Math.min(Math.max(v, lo), hi)

/**
 * One window over a categorical dataset, driven by every input a chart
 * gets: mouse drag to box-select, wheel (with ⌘/ctrl) to zoom at the
 * cursor, two-finger pinch, one-finger pan once zoomed, double-tap to
 * reset — plus imperative `zoomIn`/`zoomOut` for the on-screen buttons.
 *
 * Listeners are attached natively rather than through React props for two
 * reasons: Recharts overwrites a chart's `onTouch*` props with its own
 * tooltip handlers, so touch gestures can never reach it that way; and
 * React's wheel listener is passive, so `preventDefault` on it does
 * nothing and the page scrolls away underneath the zoom.
 */
export function useChartWindow({
  length,
  minSpan = 2,
  disabled = false,
  orientation = "x",
  insetStart = 0,
  insetEnd = 0,
  wheelZoom = false,
}: UseChartWindowOptions): UseChartWindowResult {
  const ref = React.useRef<HTMLDivElement>(null)
  const last = Math.max(0, length - 1)

  // The window lives in a ref so a gesture can read the value it just
  // wrote; state is only the render trigger.
  const win = React.useRef<[number, number]>([0, last])
  const [, bump] = React.useReducer((n: number) => n + 1, 0)
  const [selection, setSelection] = React.useState<ChartWindowSelection | null>(
    null
  )

  const setWin = React.useCallback((next: [number, number]) => {
    if (next[0] === win.current[0] && next[1] === win.current[1]) return
    win.current = next
    bump()
  }, [])

  // A new dataset invalidates any window over the old one.
  React.useEffect(() => {
    win.current = [0, Math.max(0, length - 1)]
    setSelection(null)
    bump()
  }, [length])

  const zoomAround = React.useCallback(
    (factor: number, focal: number, from?: [number, number]) => {
      const [s, e] = from ?? win.current
      const span = e - s + 1
      const next = clamp(
        Math.round(span * factor),
        Math.min(minSpan, length),
        length
      )
      if (next === span) return
      const anchor = s + focal * (span - 1)
      const start = clamp(
        Math.round(anchor - focal * (next - 1)),
        0,
        length - next
      )
      setWin([start, start + next - 1])
    },
    [length, minSpan, setWin]
  )

  const reset = React.useCallback(() => {
    setWin([0, Math.max(0, length - 1)])
  }, [length, setWin])

  const zoomIn = React.useCallback(() => zoomAround(0.6, 0.5), [zoomAround])
  const zoomOut = React.useCallback(
    () => zoomAround(1 / 0.6, 0.5),
    [zoomAround]
  )

  const setWindow = React.useCallback(
    (start: number, end: number) => {
      const lo = clamp(Math.min(start, end), 0, Math.max(0, length - 1))
      const hi = clamp(Math.max(start, end), lo, Math.max(0, length - 1))
      setWin([lo, hi])
    },
    [length, setWin]
  )

  React.useEffect(() => {
    const el = ref.current
    if (!el || disabled || length === 0) return

    const pointers = new Map<number, { x: number; y: number }>()
    let drag: {
      mode: "select" | "pan"
      at: number
      from: [number, number]
    } | null = null
    let pinch: {
      distance: number
      focal: number
      from: [number, number]
    } | null = null

    const fractionOf = (clientX: number, clientY: number) => {
      const rect = el.getBoundingClientRect()
      const total =
        (orientation === "x" ? rect.width : rect.height) - insetStart - insetEnd
      if (total <= 0) return 0
      const pos =
        (orientation === "x" ? clientX - rect.left : clientY - rect.top) -
        insetStart
      return clamp(pos / total, 0, 1)
    }

    const spread = () => {
      const [a, b] = [...pointers.values()]
      return Math.hypot(a.x - b.x, a.y - b.y) || 1
    }

    const onPointerDown = (e: PointerEvent) => {
      pointers.set(e.pointerId, { x: e.clientX, y: e.clientY })

      if (pointers.size === 2) {
        drag = null
        setSelection(null)
        const [a, b] = [...pointers.values()]
        pinch = {
          distance: spread(),
          focal: fractionOf((a.x + b.x) / 2, (a.y + b.y) / 2),
          from: win.current,
        }
        return
      }
      if (pointers.size !== 1) return

      const at = fractionOf(e.clientX, e.clientY)
      if (e.pointerType === "mouse") {
        if (e.button !== 0) return
        drag = { mode: "select", at, from: win.current }
        setSelection({ from: at, to: at })
      } else if (win.current[1] - win.current[0] + 1 < length) {
        // One finger pans, but only while zoomed — otherwise it belongs to
        // the page, which is still trying to scroll.
        drag = { mode: "pan", at, from: win.current }
      }
      if (drag) el.setPointerCapture(e.pointerId)
    }

    const onPointerMove = (e: PointerEvent) => {
      if (!pointers.has(e.pointerId)) return
      pointers.set(e.pointerId, { x: e.clientX, y: e.clientY })

      if (pinch && pointers.size >= 2) {
        e.preventDefault()
        zoomAround(pinch.distance / spread(), pinch.focal, pinch.from)
        return
      }
      if (!drag) return

      const at = fractionOf(e.clientX, e.clientY)
      if (drag.mode === "select") {
        setSelection({ from: drag.at, to: at })
        return
      }
      e.preventDefault()
      const [s0, e0] = drag.from
      const span = e0 - s0 + 1
      const shift = Math.round((drag.at - at) * span)
      const start = clamp(s0 + shift, 0, length - span)
      setWin([start, start + span - 1])
    }

    const endPointer = (e: PointerEvent) => {
      pointers.delete(e.pointerId)
      if (pointers.size < 2) pinch = null

      if (drag?.mode === "select") {
        // Read the window off the drag *now*: the updater below runs on a
        // later render, by which point `drag` has already been cleared.
        const [from, to] = drag.from
        setSelection((current) => {
          if (current && Math.abs(current.to - current.from) > 0.02) {
            const span = to - from + 1
            const a = Math.round(
              from + Math.min(current.from, current.to) * (span - 1)
            )
            const b = Math.round(
              from + Math.max(current.from, current.to) * (span - 1)
            )
            if (b - a + 1 >= minSpan) setWin([a, b])
          }
          return null
        })
      }
      if (pointers.size === 0) drag = null
    }

    const onWheel = (e: WheelEvent) => {
      if (!wheelZoom && !e.ctrlKey && !e.metaKey) return
      e.preventDefault()
      zoomAround(e.deltaY > 0 ? 1.25 : 0.8, fractionOf(e.clientX, e.clientY))
    }

    const onDoubleClick = () => reset()

    el.addEventListener("pointerdown", onPointerDown)
    el.addEventListener("pointermove", onPointerMove, { passive: false })
    el.addEventListener("pointerup", endPointer)
    el.addEventListener("pointercancel", endPointer)
    el.addEventListener("wheel", onWheel, { passive: false })
    el.addEventListener("dblclick", onDoubleClick)
    return () => {
      el.removeEventListener("pointerdown", onPointerDown)
      el.removeEventListener("pointermove", onPointerMove)
      el.removeEventListener("pointerup", endPointer)
      el.removeEventListener("pointercancel", endPointer)
      el.removeEventListener("wheel", onWheel)
      el.removeEventListener("dblclick", onDoubleClick)
    }
  }, [
    disabled,
    length,
    minSpan,
    orientation,
    insetStart,
    insetEnd,
    wheelZoom,
    zoomAround,
    reset,
    setWin,
  ])

  const [start, end] = win.current
  const isZoomed = start > 0 || end < last

  return {
    start,
    end,
    span: end - start + 1,
    isZoomed,
    slice: React.useCallback(
      <T,>(data: T[]) => data.slice(start, end + 1),
      [start, end]
    ),
    selection,
    zoomIn,
    zoomOut,
    reset,
    setWindow,
    bind: {
      ref,
      style: {
        // While zoomed the chart owns the gesture; before that the page
        // keeps its scroll along the cross axis.
        touchAction: isZoomed
          ? "none"
          : orientation === "x"
            ? "pan-y"
            : "pan-x",
        WebkitUserSelect: selection ? "none" : undefined,
        userSelect: selection ? "none" : undefined,
      },
    },
  }
}

/** The band highlighted while dragging a zoom selection. Render inside the
 *  element bound by `useChartWindow`, which must be `relative`. */
export function ChartWindowSelectionOverlay({
  selection,
  orientation = "x",
  insetStart = 0,
  insetEnd = 0,
  className,
}: {
  selection: ChartWindowSelection | null
  orientation?: "x" | "y"
  insetStart?: number
  insetEnd?: number
  className?: string
}) {
  if (!selection) return null
  const lo = Math.min(selection.from, selection.to)
  const hi = Math.max(selection.from, selection.to)
  const track = `calc(100% - ${insetStart + insetEnd}px)`
  const offset = `calc(${insetStart}px + ${lo} * ${track})`
  const size = `calc(${hi - lo} * ${track})`

  return (
    <div
      aria-hidden="true"
      className={cn(
        "bg-foreground/[0.07] border-foreground/20 pointer-events-none absolute z-10 border-x",
        className
      )}
      style={
        orientation === "x"
          ? { left: offset, width: size, top: 0, bottom: 0 }
          : { top: offset, height: size, left: 0, right: 0 }
      }
    />
  )
}

/** Zoom in / out / reset. Touch-sized targets, always visible on coarse
 *  pointers where there is no hover to reveal them. */
export function ChartZoomControls({
  onZoomIn,
  onZoomOut,
  onReset,
  isZoomed,
  className,
}: {
  onZoomIn: () => void
  onZoomOut: () => void
  onReset: () => void
  isZoomed: boolean
  className?: string
}) {
  const button =
    "flex size-9 items-center justify-center text-muted-foreground hover:text-foreground disabled:opacity-40 transition-colors"

  return (
    <div
      className={cn(
        "border-border/60 bg-background/90 absolute top-2 right-2 z-20 flex items-center rounded-lg border shadow-sm backdrop-blur",
        // Hidden until wanted: a permanent overlay sits on top of the
        // chart's own labels on a phone. Hover reveals it where there is a
        // hover; a pinch reveals it everywhere, which is also the only
        // moment a touch user needs the way back out.
        "opacity-0 transition-opacity group-hover/chart:opacity-100 focus-within:opacity-100",
        isZoomed && "opacity-100",
        className
      )}
    >
      <button
        type="button"
        onClick={onZoomOut}
        className={button}
        aria-label="Zoom out"
      >
        <svg
          viewBox="0 0 16 16"
          className="size-4"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.6}
          strokeLinecap="round"
        >
          <path d="M4 8h8" />
        </svg>
      </button>
      <button
        type="button"
        onClick={onZoomIn}
        className={button}
        aria-label="Zoom in"
      >
        <svg
          viewBox="0 0 16 16"
          className="size-4"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.6}
          strokeLinecap="round"
        >
          <path d="M8 4v8M4 8h8" />
        </svg>
      </button>
      <button
        type="button"
        onClick={onReset}
        disabled={!isZoomed}
        className={button}
        aria-label="Reset zoom"
      >
        <svg
          viewBox="0 0 16 16"
          className="size-4"
          fill="none"
          stroke="currentColor"
          strokeWidth={1.6}
          strokeLinecap="round"
          strokeLinejoin="round"
        >
          <path d="M13 8a5 5 0 1 1-1.6-3.7" />
          <path d="M13 3v2.5h-2.5" />
        </svg>
      </button>
    </div>
  )
}

"use client"

import * as React from "react"

import { cn } from "@/lib/utils"

/**
 * Container-driven responsiveness.
 *
 * Everything here measures the chart's own box, never the viewport: a chart
 * in a 320px sidebar on a desktop has exactly the problems a chart on a
 * phone has, and viewport media queries get that wrong in both directions.
 */

/** Container widths, not viewport widths. */
export const CHART_BREAKPOINTS = {
  base: 0,
  sm: 420,
  md: 640,
  lg: 900,
  xl: 1200,
} as const

export type ChartBreakpoint = keyof typeof CHART_BREAKPOINTS

/** A plain value, or one per container-width breakpoint. */
export type Responsive<T> = T | Partial<Record<ChartBreakpoint, T>>

const ORDER: ChartBreakpoint[] = ["base", "sm", "md", "lg", "xl"]

function isBreakpointMap<T>(
  value: Responsive<T>
): value is Partial<Record<ChartBreakpoint, T>> {
  return (
    typeof value === "object" &&
    value !== null &&
    ORDER.some((k) => k in (value as object))
  )
}

/** Pick the value for the widest breakpoint the container has reached. */
export function resolveResponsive<T>(
  value: Responsive<T> | undefined,
  width: number,
  fallback: T
): T {
  if (value === undefined) return fallback
  if (!isBreakpointMap(value)) return value
  let resolved = fallback
  for (const key of ORDER) {
    const candidate = value[key]
    if (candidate !== undefined && width >= CHART_BREAKPOINTS[key]) {
      resolved = candidate
    }
  }
  return resolved
}

/** Measured width of an element. 0 until the first observation, which is
 *  the signal to render nothing rather than a chart at the wrong size. */
export function useChartSize<T extends HTMLElement>() {
  const ref = React.useRef<T>(null)
  const [width, setWidth] = React.useState(0)

  React.useEffect(() => {
    const el = ref.current
    if (!el) return
    setWidth(Math.round(el.getBoundingClientRect().width))
    const observer = new ResizeObserver(([entry]) => {
      setWidth(Math.round(entry.contentRect.width))
    })
    observer.observe(el)
    return () => observer.disconnect()
  }, [])

  return { ref, width }
}

/**
 * Recharts' `interval` (categories skipped between drawn ticks) that keeps
 * labels from colliding at the measured width. `0` draws every tick.
 */
export function autoTickInterval(
  count: number,
  width: number,
  approxLabelPx = 48
): number {
  if (!width || count <= 1) return 0
  const fits = Math.max(1, Math.floor(width / approxLabelPx))
  if (count <= fits) return 0
  return Math.ceil(count / fits) - 1
}

/**
 * What to do when the categories outnumber the pixels.
 *
 * `compress` squeezes them into the container (the default, and what every
 * chart did before). `scroll` gives each category a floor width and lets
 * the plot overflow, which is the only honest option once bars are thinner
 * than the gaps between them.
 */
export type ChartOverflow = "compress" | "scroll"

export interface ChartScrollAreaProps {
  /** Which way the categories run. `x` scrolls sideways, `y` down. */
  axis?: "x" | "y"
  /** Floor size of the plot along `axis`, px. Below this it just fits. */
  minSize: number
  /** Cap on the visible box along `axis` when scrolling down. */
  maxHeight?: number
  className?: string
  children: React.ReactNode
}

/**
 * Scroll container for an oversized plot.
 *
 * `overscroll-contain` matters more than it looks: without it a sideways
 * swipe on iOS runs past the end of the chart and triggers back-navigation.
 */
export function ChartScrollArea({
  axis = "x",
  minSize,
  maxHeight,
  className,
  children,
}: ChartScrollAreaProps) {
  const horizontal = axis === "x"
  return (
    <div
      className={cn(
        "relative",
        horizontal
          ? "overflow-x-auto overflow-y-hidden overscroll-x-contain"
          : "overflow-x-hidden overflow-y-auto overscroll-y-contain",
        // Thin, unobtrusive scrollbar; still a real one, so the affordance
        // survives for anyone who needs it.
        "[&::-webkit-scrollbar]:h-1.5 [&::-webkit-scrollbar]:w-1.5",
        "[&::-webkit-scrollbar-thumb]:bg-border [&::-webkit-scrollbar-thumb]:rounded-full",
        "[&::-webkit-scrollbar-track]:bg-transparent",
        className
      )}
      style={{
        maxHeight: horizontal ? undefined : maxHeight,
        touchAction: horizontal ? "pan-x pan-y" : "pan-y",
      }}
    >
      <div style={horizontal ? { minWidth: minSize } : { minHeight: minSize }}>
        {children}
      </div>
    </div>
  )
}

export interface CategoryLayout {
  /** Width the plot renders at — the container's, unless it overflows. */
  plotWidth: number
  /** Height the plot renders at. */
  plotHeight: number
  /** True when the plot is larger than its container along `axis`. */
  scrolls: boolean
  /** Screen axis the categories run along. */
  axis: "x" | "y"
  /** Height of the visible box when the plot scrolls downwards. */
  viewportHeight: number
}

/**
 * How big a category chart should draw itself, and whether that overflows.
 *
 * `minCategorySize` is the room one bar/point needs to stay legible. Below
 * it, `compress` keeps squeezing — which is how forty bars become a smear —
 * and `scroll` starts overflowing instead.
 */
export function useCategoryLayout({
  count,
  containerWidth,
  aspectRatio,
  minHeight,
  overflow,
  minCategorySize,
  axis = "x",
}: {
  count: number
  containerWidth: number
  aspectRatio: Responsive<number> | undefined
  minHeight: number
  overflow: ChartOverflow
  minCategorySize: number
  axis?: "x" | "y"
}): CategoryLayout {
  const aspect = resolveResponsive(aspectRatio, containerWidth, 2) || 2
  // Before the first measurement, assume a desktop-ish width rather than
  // rendering a zero-height chart for one frame.
  const width = containerWidth || 640
  const height = Math.max(minHeight, Math.round(width / aspect))
  const wanted = count * minCategorySize

  if (
    overflow === "scroll" &&
    axis === "x" &&
    containerWidth &&
    wanted > width
  ) {
    return {
      plotWidth: wanted,
      plotHeight: height,
      scrolls: true,
      axis,
      viewportHeight: height,
    }
  }
  if (overflow === "scroll" && axis === "y" && wanted > height) {
    return {
      plotWidth: width,
      plotHeight: wanted,
      scrolls: true,
      axis,
      viewportHeight: height,
    }
  }
  return {
    plotWidth: width,
    plotHeight: height,
    scrolls: false,
    axis,
    viewportHeight: height,
  }
}

/** Wraps a plot in a scroll container only when it actually overflows. */
export function ChartPlotArea({
  layout,
  className,
  children,
}: {
  layout: CategoryLayout
  className?: string
  children: React.ReactNode
}) {
  if (!layout.scrolls) return <>{children}</>
  return (
    <ChartScrollArea
      axis={layout.axis}
      minSize={layout.axis === "x" ? layout.plotWidth : layout.plotHeight}
      maxHeight={layout.axis === "y" ? layout.viewportHeight : undefined}
      className={className}
    >
      {children}
    </ChartScrollArea>
  )
}

/** Props every category chart shares for fitting itself to its container. */
export interface CategoryChartLayoutProps {
  /**
   * Width ÷ height. A plain number, or one per container-width breakpoint
   * (`{ base: 1.2, md: 2 }`) — measured on the chart's own box, so a chart
   * in a narrow card gets the narrow treatment on a desktop too.
   */
  aspectRatio?: Responsive<number>
  /** Floor on the plot height, px. Stops a phone-width chart collapsing. */
  minHeight?: number
  /**
   * What to do when the categories outnumber the pixels. `compress` (the
   * default) squeezes them in; `scroll` gives each one `minCategorySize`
   * and lets the plot overflow — sideways for a category X-axis, downwards
   * for a category Y-axis.
   */
  overflow?: ChartOverflow
  /** Room each category needs before `scroll` starts overflowing, px. */
  minCategorySize?: number
  /** Drag / pinch / wheel zoom. Ignored while the plot is scrolling. */
  zoomable?: boolean
  /** Let a bare wheel zoom, rather than only ⌘/ctrl + wheel. */
  wheelZoom?: boolean
  /** Draw the +/−/reset buttons. */
  showZoomControls?: boolean
}

"use client"

import * as React from "react"

/**
 * One place to restyle every chart.
 *
 * The registry components read their *visual* defaults from here instead of
 * hard-coding them, so a host (the docs site, a customer app, chatplotdb)
 * can flip the whole surface to a different look with one provider rather
 * than threading twenty props through every chart payload. Explicit props
 * always win over the theme; the theme only supplies defaults.
 */

/** Shape of a reference-line label. */
export type ChartTagVariant = "plain" | "pill" | "flag"

/** How the emphasised category tick is marked out. */
export type ChartTickVariant = "plain" | "pill" | "underline"

/** Fill treatment for a mark. `none` is a flat fill. */
export type ChartPatternKind =
  | "none"
  | "hatch"
  | "hatch-dense"
  | "dots"
  | "grid"

export interface ChartTheme {
  /** Series colours, in order. */
  palette: string[]
  /** Fill for de-emphasised marks (the grey bars behind the active one). */
  mutedColor: string
  /** Texture painted over de-emphasised marks. */
  mutedPattern: ChartPatternKind
  /** Texture painted over emphasised marks. */
  activePattern: ChartPatternKind
  /** Corner radius for bars and segments, in px. */
  barRadius: number
  /** `round` caps a bar at half its width — the pill-top look. */
  barCap: "flat" | "round"
  maxBarSize: number
  /** Grid dash array; `""` draws solid lines. */
  gridDash: string
  gridOpacity: number
  tickFontSize: number
  /** How the emphasised category tick is marked out. */
  activeTickVariant: ChartTickVariant
  /** Colours for the `pill` and `underline` tick variants. */
  activeTickBackground: string
  activeTickForeground: string
  /** Shape of the reference-line label ("Avg 6.8%"). */
  tagVariant: ChartTagVariant
  /** Colours for the `flag` and `pill` tag variants. */
  tagBackground: string
  tagForeground: string
  animate: boolean
  animationDuration: number
}

/** Current library look. Changing these changes every chart's default. */
export const defaultChartTheme: ChartTheme = {
  palette: [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)",
    "var(--chart-4)",
    "var(--chart-5)",
  ],
  mutedColor: "var(--muted)",
  mutedPattern: "none",
  activePattern: "none",
  barRadius: 4,
  barCap: "flat",
  maxBarSize: 50,
  gridDash: "3 3",
  gridOpacity: 0.5,
  tickFontSize: 12,
  activeTickVariant: "plain",
  activeTickBackground: "color-mix(in oklab, var(--chart-3) 15%, transparent)",
  activeTickForeground: "var(--chart-3)",
  // `plain` by default, and deliberately: a filled chip floating over the
  // plot reads as a tooltip someone forgot to dismiss. Presets opt in.
  tagVariant: "plain",
  tagBackground: "var(--foreground)",
  tagForeground: "var(--background)",
  animate: true,
  animationDuration: 600,
}

/** The fintech-dashboard look: hatched grey bars, one vivid active mark,
 *  generous pill radii, dotted grid, pill axis tick. */
export const dashboardChartTheme: ChartTheme = {
  ...defaultChartTheme,
  mutedColor: "color-mix(in oklab, var(--muted-foreground) 14%, transparent)",
  mutedPattern: "hatch",
  activePattern: "hatch",
  barRadius: 10,
  barCap: "round",
  maxBarSize: 64,
  gridDash: "2 6",
  gridOpacity: 0.35,
  activeTickVariant: "pill",
  tagVariant: "flag",
}

/** Quietest possible: thin marks, faint grid, no annotation chrome. */
export const minimalChartTheme: ChartTheme = {
  ...defaultChartTheme,
  barRadius: 2,
  gridDash: "",
  gridOpacity: 0.25,
  tagVariant: "plain",
  activeTickVariant: "plain",
}

export const chartThemePresets = {
  default: defaultChartTheme,
  dashboard: dashboardChartTheme,
  minimal: minimalChartTheme,
} satisfies Record<string, ChartTheme>

export type ChartThemePreset = keyof typeof chartThemePresets

const ChartThemeContext = React.createContext<ChartTheme | null>(null)

export interface ChartThemeProviderProps {
  /** A named preset, or the theme to merge onto the inherited one. */
  preset?: ChartThemePreset
  theme?: Partial<ChartTheme>
  children: React.ReactNode
}

/** Providers nest: an inner one merges onto whatever is already in scope,
 *  so a single card can deviate without redefining the whole theme. */
export function ChartThemeProvider({
  preset,
  theme,
  children,
}: ChartThemeProviderProps) {
  const inherited = React.useContext(ChartThemeContext) ?? defaultChartTheme
  const base = preset ? chartThemePresets[preset] : inherited
  const value = React.useMemo(
    () => (theme ? { ...base, ...theme } : base),
    // `theme` is usually an object literal; hashing its entries keeps the
    // context value stable across renders so charts don't re-render for free.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [base, JSON.stringify(theme ?? null)]
  )

  return (
    <ChartThemeContext.Provider value={value}>
      {children}
    </ChartThemeContext.Provider>
  )
}

/**
 * Read the active theme, with per-call overrides layered on top.
 * `undefined` overrides are dropped, so `useChartTheme({ barRadius })` with
 * an unset prop still yields the themed value.
 */
export function useChartTheme(overrides?: Partial<ChartTheme>): ChartTheme {
  const theme = React.useContext(ChartThemeContext) ?? defaultChartTheme
  return React.useMemo(() => {
    if (!overrides) return theme
    const merged = { ...theme }
    for (const [key, value] of Object.entries(overrides)) {
      if (value !== undefined) {
        ;(merged as Record<string, unknown>)[key] = value
      }
    }
    return merged
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [theme, JSON.stringify(overrides ?? null)])
}

"use client"

import * as React from "react"

import type { ChartPatternKind } from "./chart-theme"

/**
 * SVG `<pattern>` fills — the diagonal hatch / dot textures that give
 * dashboard bars their material feel instead of a flat wash of colour.
 *
 * Recharts renders unrecognised children verbatim, so `<ChartPatternDefs>`
 * can sit directly inside a `<BarChart>` next to the axes and the marks
 * reference it through `patternFill()`.
 */

export interface ChartPatternSpec {
  id: string
  kind: ChartPatternKind
  /** Stroke/dot colour drawn on top of `background`. */
  color: string
  /** Fill behind the texture. Defaults to `color` at low opacity. */
  background?: string
  /** Tile size in px — smaller means denser. */
  size?: number
  strokeWidth?: number
  /** Rotation of the tile, degrees. 45 gives the classic hatch. */
  angle?: number
  /** Opacity of the texture strokes (not the background). */
  opacity?: number
}

const TILE: Record<Exclude<ChartPatternKind, "none">, number> = {
  hatch: 7,
  "hatch-dense": 4,
  dots: 6,
  grid: 8,
}

/** One `<pattern>`. Render inside a `<defs>`; use `ChartPatternDefs` for that. */
export function ChartPattern({
  id,
  kind,
  color,
  background,
  size,
  strokeWidth = 1.5,
  angle = 45,
  opacity = 1,
}: ChartPatternSpec) {
  if (kind === "none") return null

  const tile = size ?? TILE[kind]
  const bg = background ?? "transparent"

  return (
    <pattern
      id={id}
      patternUnits="userSpaceOnUse"
      width={tile}
      height={tile}
      patternTransform={kind === "dots" ? undefined : `rotate(${angle})`}
    >
      <rect width={tile} height={tile} fill={bg} />
      {kind === "dots" ? (
        <circle
          cx={tile / 2}
          cy={tile / 2}
          r={strokeWidth}
          fill={color}
          opacity={opacity}
        />
      ) : (
        <>
          <line
            x1={0}
            y1={0}
            x2={0}
            y2={tile}
            stroke={color}
            strokeWidth={strokeWidth}
            opacity={opacity}
          />
          {kind === "grid" && (
            <line
              x1={0}
              y1={0}
              x2={tile}
              y2={0}
              stroke={color}
              strokeWidth={strokeWidth}
              opacity={opacity}
            />
          )}
        </>
      )}
    </pattern>
  )
}

/**
 * Every pattern a chart needs, as a `<defs>` element.
 *
 * A *function*, not a component, because Recharts walks its children by
 * type and silently drops the ones it doesn't recognise — a wrapper
 * component never reaches the SVG, and every `url(#…)` fill then resolves
 * to nothing (invisible marks). Calling it inlines a real `<defs>` into the
 * children array, which Recharts passes through:
 *
 * ```tsx
 * <BarChart>{chartPatternDefs([{ id, kind: "hatch", color, background }])}</BarChart>
 * ```
 *
 * Paint servers must live in the *same* SVG root as the marks that use
 * them, so this cannot be hoisted into a sprite elsewhere on the page.
 * Returns `null` when nothing needs a texture.
 */
export function chartPatternDefs(
  patterns: Array<ChartPatternSpec | null | undefined>
) {
  const active = patterns.filter(
    (p): p is ChartPatternSpec => !!p && p.kind !== "none"
  )
  if (!active.length) return null

  return (
    <defs key="chart-patterns">
      {active.map((p) => (
        <ChartPattern key={p.id} {...p} />
      ))}
    </defs>
  )
}

/** The `fill` value for a mark: the pattern when one applies, else the
 *  plain colour. Keeps call sites free of `url(#…)` string-building. */
export function patternFill(
  color: string,
  kind: ChartPatternKind | undefined,
  id: string | undefined
): string {
  if (!kind || kind === "none" || !id) return color
  return `url(#${id})`
}

/** Collision-free pattern ids for one chart instance. */
export function useChartPatternIds(...keys: string[]): Record<string, string> {
  const uid = React.useId().replace(/:/g, "")
  return React.useMemo(
    () => Object.fromEntries(keys.map((k) => [k, `sc-${k}-${uid}`])),
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [uid, keys.join("|")]
  )
}

"use client"

import * as React from "react"

import type { ChartTagVariant, ChartTickVariant } from "./chart-theme"

/**
 * Annotation renderers for Recharts cartesian charts.
 *
 * These are exported as *render functions* rather than components on
 * purpose: Recharts discovers `ReferenceLine` / axis `tick` children by
 * type, so a wrapper component would be invisible to it. A function passed
 * to `label={...}` / `tick={...}` is called with the layout props and can
 * return whatever SVG it likes.
 */

interface ViewBox {
  x?: number
  y?: number
  width?: number
  height?: number
}

/** Rough advance width. Charts render in the app's sans stack, so a fixed
 *  ratio beats measuring the DOM for a label this small. Override with
 *  `width` when a font makes it visibly wrong. */
function estimateWidth(text: string, fontSize: number) {
  return text.length * fontSize * 0.58
}

/** Anything Recharts can use as a `label` / `tick`: it is handed the layout
 *  props and returns SVG. Pass your own to replace a built-in variant
 *  wholesale rather than configuring it. */
export type ChartLabelRenderer = (props: {
  viewBox?: ViewBox
  x?: number
  y?: number
  payload?: { value?: string | number }
}) => React.ReactElement<SVGElement>

export interface ChartTagLabelOptions {
  /**
   * `plain` prints the text alone, `pill` sets it in a rounded chip and
   * `flag` gives the chip a point aimed along the line. Default `plain`:
   * a filled chip floating over a plot reads as a stuck tooltip.
   */
  variant?: ChartTagVariant
  background?: string
  foreground?: string
  fontSize?: number
  /** Which end of the line the label hangs off. */
  side?: "left" | "right"
  /** Horizontal nudge, px. Negative pulls the label outside the plot. */
  dx?: number
  /** Vertical nudge, px. `plain` sits above the line by default. */
  dy?: number
  paddingX?: number
  height?: number
  radius?: number
  /** Length of the point on the `flag` variant. */
  tip?: number
  /** Skip the estimator when you know the exact width. */
  width?: number
}

/**
 * Label for a reference line.
 *
 * ```tsx
 * <ReferenceLine y={avg} label={chartTagLabel("Avg 6.8%", { variant: "flag" })} />
 * ```
 */
export function chartTagLabel(
  text: string,
  options: ChartTagLabelOptions = {}
) {
  const {
    variant = "plain",
    background = "var(--foreground)",
    foreground = "var(--background)",
    fontSize = 11,
    side = "left",
    dx = 0,
    dy,
    paddingX = 8,
    height = 22,
    radius = 6,
    tip = 6,
    width,
  } = options

  return function TagLabel(props: { viewBox?: ViewBox }) {
    const box = props.viewBox ?? {}
    const boxX = box.x ?? 0
    const boxY = box.y ?? 0
    const boxWidth = box.width ?? 0

    if (variant === "plain") {
      const anchor = side === "left" ? "start" : "end"
      const x = side === "left" ? boxX + dx : boxX + boxWidth + dx
      return (
        <text
          x={x}
          y={boxY + (dy ?? -6)}
          textAnchor={anchor}
          fill="var(--muted-foreground)"
          fontSize={fontSize}
          fontWeight={500}
          style={{ pointerEvents: "none" }}
        >
          {text}
        </text>
      )
    }

    const pointed = variant === "flag"
    const point = pointed ? tip : 0
    const w = width ?? estimateWidth(text, fontSize) + paddingX * 2 + point
    const h = height
    const r = Math.min(radius, h / 2)
    const x = side === "left" ? boxX + dx : boxX + boxWidth - w + dx
    const y = boxY - h / 2 + (dy ?? 0)

    // Rounded on the blunt end; the flag variant points along the line.
    const path = !pointed
      ? `M ${r} 0 H ${w - r} A ${r} ${r} 0 0 1 ${w} ${r} V ${h - r} A ${r} ${r} 0 0 1 ${w - r} ${h} H ${r} A ${r} ${r} 0 0 1 0 ${h - r} V ${r} A ${r} ${r} 0 0 1 ${r} 0 Z`
      : side === "left"
        ? `M ${r} 0 H ${w - point} L ${w} ${h / 2} L ${w - point} ${h} H ${r} A ${r} ${r} 0 0 1 0 ${h - r} V ${r} A ${r} ${r} 0 0 1 ${r} 0 Z`
        : `M ${point} 0 H ${w - r} A ${r} ${r} 0 0 1 ${w} ${r} V ${h - r} A ${r} ${r} 0 0 1 ${w - r} ${h} H ${point} L 0 ${h / 2} Z`

    return (
      <g transform={`translate(${x}, ${y})`} style={{ pointerEvents: "none" }}>
        <path d={path} fill={background} />
        <text
          x={pointed && side === "right" ? point + (w - point) / 2 : (w - point) / 2}
          y={h / 2}
          textAnchor="middle"
          dominantBaseline="central"
          fill={foreground}
          fontSize={fontSize}
          fontWeight={500}
        >
          {text}
        </text>
      </g>
    )
  }
}

export interface ChartPillTickOptions {
  /** `plain` marks the active tick with weight and colour only. */
  variant?: ChartTickVariant
  fontSize?: number
  background?: string
  foreground?: string
  mutedForeground?: string
  paddingX?: number
  height?: number
  formatter?: (value: string) => string
}

/**
 * Category-axis tick that marks out one category.
 *
 * ```tsx
 * <XAxis dataKey="label" tick={chartActiveTick("May", { variant: "pill" })} />
 * ```
 */
export function chartActiveTick(
  activeLabel: string | null | undefined,
  options: ChartPillTickOptions = {}
) {
  const {
    variant = "plain",
    fontSize = 12,
    background = "color-mix(in oklab, var(--chart-3) 15%, transparent)",
    foreground = "var(--chart-3)",
    mutedForeground = "var(--muted-foreground)",
    paddingX = 12,
    height = 26,
    formatter,
  } = options

  return function ActiveTick(props: {
    x?: number
    y?: number
    payload?: { value?: string | number }
  }) {
    const raw = String(props.payload?.value ?? "")
    const text = formatter ? formatter(raw) : raw
    const active = activeLabel != null && raw === activeLabel
    const w = estimateWidth(text, fontSize) + paddingX * 2

    return (
      <g transform={`translate(${props.x ?? 0}, ${props.y ?? 0})`}>
        {active && variant === "pill" && (
          <rect
            x={-w / 2}
            y={0}
            width={w}
            height={height}
            rx={height / 2}
            fill={background}
          />
        )}
        {active && variant === "underline" && (
          <rect
            x={-w / 4}
            y={height - 2}
            width={w / 2}
            height={2}
            rx={1}
            fill={foreground}
          />
        )}
        <text
          x={0}
          y={height / 2}
          textAnchor="middle"
          dominantBaseline="central"
          fontSize={fontSize}
          fontWeight={active ? 600 : 400}
          fill={active ? foreground : mutedForeground}
        >
          {text}
        </text>
      </g>
    )
  }
}

/** @deprecated Use `chartActiveTick`, which takes a `variant`. */
export const chartPillTick = (
  activeLabel: string | null | undefined,
  options: ChartPillTickOptions = {}
) => chartActiveTick(activeLabel, { variant: "pill", ...options })

export interface ChartValueLabelOptions {
  fontSize?: number
  color?: string
  /** Gap between the mark and the label, px. */
  offset?: number
  fontWeight?: number
}

/**
 * `LabelList` content that prints the value above *only* the emphasised
 * marks, so a dense chart gets one readable callout instead of forty.
 */
export function chartActiveValueLabel(
  isActive: (index: number) => boolean,
  format: (value: number) => string,
  options: ChartValueLabelOptions = {}
) {
  const {
    fontSize = 13,
    color = "var(--foreground)",
    offset = 10,
    fontWeight = 600,
  } = options

  // Recharts hands `LabelList` content the raw layout props, where the
  // geometry can arrive as strings — hence the coercion rather than `??`.
  return function ActiveValueLabel(props: {
    x?: number | string
    y?: number | string
    width?: number | string
    value?: number | string
    index?: number
  }) {
    const index = props.index ?? -1
    if (!isActive(index)) return <g />
    const value = Number(props.value)
    if (!Number.isFinite(value)) return <g />
    const x = Number(props.x) || 0
    const y = Number(props.y) || 0
    const width = Number(props.width) || 0

    return (
      <text
        x={x + width / 2}
        y={y - offset}
        textAnchor="middle"
        fontSize={fontSize}
        fontWeight={fontWeight}
        fill={color}
      >
        {format(value)}
      </text>
    )
  }
}

/** Resolve `"avg" | "min" | "max" | number` against the plotted values. */
export function resolveReferenceValue(
  spec: number | "avg" | "min" | "max",
  values: number[]
): number | null {
  if (typeof spec === "number") return Number.isFinite(spec) ? spec : null
  const finite = values.filter((v) => Number.isFinite(v))
  if (!finite.length) return null
  if (spec === "min") return Math.min(...finite)
  if (spec === "max") return Math.max(...finite)
  return finite.reduce((a, b) => a + b, 0) / finite.length
}

"use client"

import { extent, max, min } from "d3-array"
import {
  scaleBand,
  scaleLinear,
  scaleLog,
  scaleOrdinal,
  scaleTime,
} from "d3-scale"

// Re-export D3 utilities for convenience
export { scaleLinear, scaleBand, scaleTime, scaleLog, scaleOrdinal }
export { max, min, extent }

// Common scale creation utilities
export interface CreateLinearScaleOptions {
  domain: [number, number]
  range: [number, number]
  nice?: boolean
  padding?: number
}

export function createLinearScale({
  domain,
  range,
  nice = true,
  padding = 0.1,
}: CreateLinearScaleOptions) {
  const [minVal, maxVal] = domain
  const paddedDomain: [number, number] = [
    minVal - (maxVal - minVal) * padding,
    maxVal + (maxVal - minVal) * padding,
  ]

  const scale = scaleLinear().domain(paddedDomain).range(range)
  return nice ? scale.nice() : scale
}

export interface CreateBandScaleOptions {
  domain: string[]
  range: [number, number]
  padding?: number
  paddingInner?: number
  paddingOuter?: number
}

export function createBandScale({
  domain,
  range,
  padding = 0.2,
  paddingInner,
  paddingOuter,
}: CreateBandScaleOptions) {
  const scale = scaleBand().domain(domain).range(range)

  if (paddingInner !== undefined && paddingOuter !== undefined) {
    return scale.paddingInner(paddingInner).paddingOuter(paddingOuter)
  }

  return scale.padding(padding)
}

// Data processing utilities
export function getDataExtent<T>(
  data: T[],
  accessor: (d: T) => number
): [number, number] {
  const values = data.map(accessor)
  return [Math.min(...values), Math.max(...values)]
}

export function normalizeData<T extends Record<string, unknown>>(
  data: T[],
  keys: string[]
): T[] {
  const maxValues = keys.reduce(
    (acc, key) => {
      acc[key] = Math.max(...data.map((d) => Number(d[key]) || 0))
      return acc
    },
    {} as Record<string, number>
  )

  return data.map((d) => {
    const normalized = { ...d }
    keys.forEach((key) => {
      if (maxValues[key] > 0) {
        ;(normalized as Record<string, unknown>)[`${key}_normalized`] =
          (Number(d[key]) || 0) / maxValues[key]
      }
    })
    return normalized
  })
}

// Color utilities
export function interpolateColor(
  color1: string,
  color2: string,
  t: number
): string {
  // Simple linear interpolation for hex colors
  const hex1 = color1.replace("#", "")
  const hex2 = color2.replace("#", "")

  const r1 = parseInt(hex1.substring(0, 2), 16)
  const g1 = parseInt(hex1.substring(2, 4), 16)
  const b1 = parseInt(hex1.substring(4, 6), 16)

  const r2 = parseInt(hex2.substring(0, 2), 16)
  const g2 = parseInt(hex2.substring(2, 4), 16)
  const b2 = parseInt(hex2.substring(4, 6), 16)

  const r = Math.round(r1 + (r2 - r1) * t)
  const g = Math.round(g1 + (g2 - g1) * t)
  const b = Math.round(b1 + (b2 - b1) * t)

  return `#${r.toString(16).padStart(2, "0")}${g.toString(16).padStart(2, "0")}${b.toString(16).padStart(2, "0")}`
}

export function generateColorScale(
  count: number,
  baseColor?: string
): string[] {
  if (count <= 0) return []

  // Default chart colors (CSS variables)
  const defaultColors = [
    "var(--chart-1)",
    "var(--chart-2)",
    "var(--chart-3)",
    "var(--chart-4)",
    "var(--chart-5)",
  ]

  if (!baseColor) {
    return Array.from(
      { length: count },
      (_, i) => defaultColors[i % defaultColors.length]
    )
  }

  // Generate shades of the base color
  return Array.from({ length: count }, (_, i) => {
    const lightness = 0.3 + (0.5 * i) / (count - 1 || 1)
    return `hsl(from ${baseColor} h s ${lightness * 100}%)`
  })
}

// Animation utilities
export function easeOutCubic(t: number): number {
  return 1 - Math.pow(1 - t, 3)
}

export function easeInOutCubic(t: number): number {
  return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2
}

export function easeOutElastic(t: number): number {
  const c4 = (2 * Math.PI) / 3
  return t === 0
    ? 0
    : t === 1
      ? 1
      : Math.pow(2, -10 * t) * Math.sin((t * 10 - 0.75) * c4) + 1
}

// Number formatting utilities
export function formatNumber(value: number, decimals = 0): string {
  if (Math.abs(value) >= 1e9) {
    return `${(value / 1e9).toFixed(decimals)}B`
  }
  if (Math.abs(value) >= 1e6) {
    return `${(value / 1e6).toFixed(decimals)}M`
  }
  if (Math.abs(value) >= 1e3) {
    return `${(value / 1e3).toFixed(decimals)}K`
  }
  return value.toFixed(decimals)
}

export function formatPercent(value: number, decimals = 1): string {
  return `${(value * 100).toFixed(decimals)}%`
}

export function formatCurrency(
  value: number,
  currency = "USD",
  locale = "en-US"
): string {
  return new Intl.NumberFormat(locale, {
    style: "currency",
    currency,
    minimumFractionDigits: 0,
    maximumFractionDigits: 2,
  }).format(value)
}

// Geometry utilities
export function polarToCartesian(
  centerX: number,
  centerY: number,
  radius: number,
  angleInDegrees: number
): { x: number; y: number } {
  const angleInRadians = ((angleInDegrees - 90) * Math.PI) / 180
  return {
    x: centerX + radius * Math.cos(angleInRadians),
    y: centerY + radius * Math.sin(angleInRadians),
  }
}

export function describeArc(
  x: number,
  y: number,
  radius: number,
  startAngle: number,
  endAngle: number
): string {
  const start = polarToCartesian(x, y, radius, endAngle)
  const end = polarToCartesian(x, y, radius, startAngle)
  const largeArcFlag = endAngle - startAngle <= 180 ? 0 : 1

  return [
    "M",
    start.x,
    start.y,
    "A",
    radius,
    radius,
    0,
    largeArcFlag,
    0,
    end.x,
    end.y,
  ].join(" ")
}

// SVG path utilities
export function linePath(points: Array<{ x: number; y: number }>): string {
  if (points.length === 0) return ""

  return points.map((p, i) => `${i === 0 ? "M" : "L"} ${p.x} ${p.y}`).join(" ")
}

export function smoothLinePath(
  points: Array<{ x: number; y: number }>,
  smoothing = 0.2
): string {
  if (points.length < 2) return linePath(points)

  const line = (
    pointA: { x: number; y: number },
    pointB: { x: number; y: number }
  ) => {
    const lengthX = pointB.x - pointA.x
    const lengthY = pointB.y - pointA.y
    return {
      length: Math.sqrt(Math.pow(lengthX, 2) + Math.pow(lengthY, 2)),
      angle: Math.atan2(lengthY, lengthX),
    }
  }

  const controlPoint = (
    current: { x: number; y: number },
    previous: { x: number; y: number } | undefined,
    next: { x: number; y: number } | undefined,
    reverse?: boolean
  ) => {
    const p = previous ?? current
    const n = next ?? current
    const l = line(p, n)
    const angle = l.angle + (reverse ? Math.PI : 0)
    const length = l.length * smoothing
    return {
      x: current.x + Math.cos(angle) * length,
      y: current.y + Math.sin(angle) * length,
    }
  }

  return points.reduce((path, point, i, arr) => {
    if (i === 0) return `M ${point.x} ${point.y}`

    const cp1 = controlPoint(arr[i - 1], arr[i - 2], point)
    const cp2 = controlPoint(point, arr[i - 1], arr[i + 1], true)

    return `${path} C ${cp1.x} ${cp1.y}, ${cp2.x} ${cp2.y}, ${point.x} ${point.y}`
  }, "")
}
